import React from "react";
import { StyleSheet, TouchableOpacity, View } from "react-native";
import Text3D from "./Text3D";

type ActionBarProps = {
  gameOver: boolean;
  onNewGame: () => void;
};

function Btn({
  label,
  onPress,
  disabled,
  color,
  textColor = "#fff",
}: {
  label: string;
  onPress: () => void;
  disabled?: boolean;
  color: string;
  textColor?: string;
}): React.ReactElement {
  return (
    <TouchableOpacity
      onPress={onPress}
      disabled={disabled}
      activeOpacity={0.8}
      style={[
        styles.btn,
        { backgroundColor: color },
        disabled && styles.btnDisabled,
      ]}
    >
      <Text3D
        style={[
          styles.btnText,
          { color: textColor },
          disabled && styles.btnTextDisabled,
        ]}
      >
        {label}
      </Text3D>
    </TouchableOpacity>
  );
}

export default function ActionBar({
  gameOver,
  onNewGame,
}: ActionBarProps): React.ReactElement | null {
  if (gameOver) {
    return (
      <View style={styles.bar}>
        <Btn
          label="🃏  New Game"
          onPress={onNewGame}
          color="#f6d43a"
          textColor="#1a1a2e"
        />
      </View>
    );
  }

  return null;
}

const styles = StyleSheet.create({
  bar: {
    flexDirection: "row",
    flexWrap: "wrap",
    justifyContent: "center",
    gap: 8,
    paddingVertical: 6,
    paddingHorizontal: 8,
  },
  btn: {
    paddingVertical: 9,
    paddingHorizontal: 18,
    borderRadius: 22,
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.3,
    shadowRadius: 3,
    elevation: 3,
  },
  btnDisabled: {
    opacity: 0.4,
  },
  btnText: {
    fontWeight: "bold",
    fontSize: 12,
    letterSpacing: 0.5,
  },
  btnTextDisabled: {},
});
